"use client";
import { useEffect, useRef, useState } from "react";

/**
 * Memantau kualitas koneksi internet.
 * - reason 'offline' : internet terputus
 * - reason 'slow'    : respons server terlalu lambat / timeout
 *
 * Dianggap bermasalah setelah `failThreshold` kali gagal berturut-turut,
 * dan pulih setelah 1 kali cek yang sehat.
 */
export function useConnectionStatus({
  url = "/api/health",
  intervalMs = 5000, // jeda cek saat koneksi normal
  recoverIntervalMs = 2000, // jeda cek saat sedang bermasalah
  timeoutMs = 5000, // lebih dari ini dianggap gagal
  slowMs = 4000, // respons lebih lambat dari ini dianggap lambat
  failThreshold = 2,
} = {}) {
  const [status, setStatus] = useState({ isOnline: true, reason: null });
  const fails = useRef(0);

  useEffect(() => {
    let stopped = false;
    let timer;

    const markBad = (reason) => {
      fails.current += 1;
      if (fails.current >= failThreshold) {
        setStatus((s) =>
          !s.isOnline && s.reason === reason ? s : { isOnline: false, reason },
        );
      }
    };

    const markGood = () => {
      fails.current = 0;
      setStatus((s) => (s.isOnline ? s : { isOnline: true, reason: null }));
    };

    const schedule = (ms) => {
      if (stopped) return;
      clearTimeout(timer);
      timer = setTimeout(check, ms);
    };

    async function check() {
      if (typeof navigator !== "undefined" && navigator.onLine === false) {
        fails.current = failThreshold;
        setStatus({ isOnline: false, reason: "offline" });
        return schedule(recoverIntervalMs);
      }

      const ctrl = new AbortController();
      const abortTimer = setTimeout(() => ctrl.abort(), timeoutMs);
      const start = Date.now();
      try {
        const res = await fetch(`${url}?t=${start}`, {
          cache: "no-store",
          signal: ctrl.signal,
        });
        const ms = Date.now() - start;
        if (!res.ok) markBad("offline");
        else if (ms > slowMs) markBad("slow");
        else markGood();
      } catch {
        markBad(ctrl.signal.aborted ? "slow" : "offline");
      } finally {
        clearTimeout(abortTimer);
        schedule(fails.current > 0 ? recoverIntervalMs : intervalMs);
      }
    }

    const onOffline = () => {
      fails.current = failThreshold;
      setStatus({ isOnline: false, reason: "offline" });
    };
    const onOnline = () => check();

    window.addEventListener("offline", onOffline);
    window.addEventListener("online", onOnline);
    check();

    return () => {
      stopped = true;
      clearTimeout(timer);
      window.removeEventListener("offline", onOffline);
      window.removeEventListener("online", onOnline);
    };
  }, [url, intervalMs, recoverIntervalMs, timeoutMs, slowMs, failThreshold]);

  return status;
}
